window.fiText=value=>{
 if(typeof value!=='string')return value;
 const dict=window.FI_TEXT;if(Object.hasOwn(dict,value))return dict[value];
 const trimmed=value.trim();if(Object.hasOwn(dict,trimmed))return value.slice(0,value.indexOf(trimmed))+dict[trimmed]+value.slice(value.indexOf(trimmed)+trimmed.length);
 if(value.length>1500||trimmed.startsWith('{')||trimmed.startsWith('['))return value;
 let result=value;for(const [source,target] of Object.entries(window.FI_PARTS).sort((a,b)=>b[0].length-a[0].length))result=result.replaceAll(source,target);
 return result.replace(/(?<![\w.])(\d+)\.(\d+)(?![\w]|\.\d)/g,'$1,$2').replace(/(?<=\d)%/g,'\u00a0%');
};
document.addEventListener('DOMContentLoaded',()=>{
 if(window.STORY_LANGUAGE!=='fi')return;
 const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);
 for(const node of nodes){if(node.parentElement?.closest('script,style,pre,code,[data-language]'))continue;const text=window.fiText(node.nodeValue);if(text!==node.nodeValue)node.nodeValue=text;}
 for(const node of document.querySelectorAll('[aria-label],img[alt]')){for(const name of ['aria-label','alt'])if(node.hasAttribute(name))node.setAttribute(name,window.fiText(node.getAttribute(name)));}
});
